private void scaffold(){ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setVerticalScrollBarEnabled(false);scroll.setBackgroundColor(BLACK);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dip(14),dip(18),dip(14),dip(20));root.setBackgroundColor(BLACK);scroll.addView(root);setContentView(scroll);LinearLayout titleRow=new LinearLayout(this);titleRow.setGravity(Gravity.CENTER_VERTICAL);root.addView(titleRow,params());TextView heading=text("SOLAR ELEVATION ALARM");heading.setTextSize(18);heading.setTypeface(null,android.graphics.Typeface.BOLD);titleRow.addView(heading,new LinearLayout.LayoutParams(0,-2,1));TextView version=text("v20261022T151029Z");version.setTextSize(10);titleRow.addView(version);}
