private String utc(long t){SimpleDateFormat f=new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss'Z'",Locale.US);f.setTimeZone(TimeZone.getTimeZone("UTC"));return t>0?f.format(new Date(t)):"none";}
private String iso(long t){return new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ssXXX",Locale.US).format(new Date(t));}
private String date(long t){return new SimpleDateFormat("EEE, yyyy-MM-dd",Locale.US).format(new Date(t));}
private String clock(long t){return new SimpleDateFormat("HH:mm:ss",Locale.US).format(new Date(t));}
private String directionName(int d){return d==1?"Ascending":d==-1?"Descending":"Both";}
private int resolved(SolarAlarmStore.Event e){return e.direction==0?e.nextDirection:e.direction;}
private List<SolarAlarmStore.Event> events(){SolarAlarmStore db=new SolarAlarmStore(this);List<SolarAlarmStore.Event> out=db.all();db.close();Collections.sort(out,(a,b)->{int da=resolved(a),dbb=resolved(b);if(da!=dbb)return da==1?-1:1;int c;try{c=new BigDecimal(a.angle).compareTo(new BigDecimal(b.angle));}catch(Exception ex){c=a.angle.compareTo(b.angle);}if(da==-1)c=-c;if(c!=0)return c;return Long.compare(a.id,b.id);});return out;}
private String locationSummary(){SharedPreferences p=getSharedPreferences("position",0);if(!p.contains("lat"))return "GPS: unavailable";long age=Math.max(0,(System.currentTimeMillis()-p.getLong("time",0))/60000L);return "GPS: "+age+" min old · "+p.getString("provider","saved");}
private boolean playing(){return SolarAlarmPlaybackService.isPlaybackActive();}
